def _make_plan(
    orders: dict[str, Order],
    lines: dict[tuple[str, str], Line],
    shipping: dict[str, tuple[Decimal, Decimal]],
    inventory: dict[tuple[str, str], int],
    preserved: Sequence[ExistingAllocation],
    unavailable_warehouses: set[str] | None = None,
) -> tuple[dict[tuple[str, str, str, str], int], dict[tuple[str, str], int]]:
    unavailable = unavailable_warehouses or set()
    reservable = set(shipping) - unavailable
    available = dict(inventory)
    allocated_inventory: dict[tuple[str, str], int] = defaultdict(int)
    final_allocations: dict[tuple[str, str, str, str], int] = defaultdict(int)
    existing_by_line: dict[tuple[str, str], int] = defaultdict(int)
    existing_by_order_warehouse: dict[str, dict[str, int]] = defaultdict(lambda: defaultdict(int))

    # All preserved allocations are committed before order processing begins.
    for allocation in preserved:
        line = lines[(allocation.order_id, allocation.line_id)]
        inv_key = (allocation.warehouse_id, line.sku)
        existing_by_line[(allocation.order_id, allocation.line_id)] += allocation.quantity
        existing_by_order_warehouse[allocation.order_id][allocation.warehouse_id] += allocation.quantity
        allocated_inventory[inv_key] += allocation.quantity
        final_allocations[(allocation.order_id, allocation.line_id, allocation.warehouse_id,
                           allocation.status)] += allocation.quantity

    for key, quantity in existing_by_line.items():
        if quantity > lines[key].requested_qty:
            raise InputError(f"existing allocations exceed requested quantity for order/line {key!r}")
    for key, quantity in allocated_inventory.items():
        on_hand = inventory.get(key, 0)
        if quantity > on_hand:
            raise InputError(f"existing allocations exceed on_hand for warehouse/SKU {key!r}")
        available[key] = on_hand - quantity
    for order_id, warehouses in existing_by_order_warehouse.items():
        if len(warehouses) > 3:
            raise InputError(f"existing allocations use more than three warehouses for {order_id!r}")

    lines_by_order: dict[str, list[Line]] = defaultdict(list)
    for line in lines.values():
        lines_by_order[line.order_id].append(line)
    for values in lines_by_order.values():
        values.sort(key=lambda item: item.line_id)

    ordered_orders = sorted(
        orders.values(), key=lambda item: (PRIORITY_RANK[item.priority], item.due_date, item.order_id)
    )
    reservable_tuple = tuple(sorted(reservable))
    for order in ordered_orders:
        order_lines = lines_by_order.get(order.order_id, [])
        prior_wh = dict(existing_by_order_warehouse.get(order.order_id, {}))
        existing_used = set(prior_wh)
        candidates: list[Candidate] = []
        warehouse_sets: set[tuple[str, ...]] = set()
        for size in range(0, min(3, len(reservable_tuple)) + 1):
            for subset in itertools.combinations(reservable_tuple, size):
                combined = tuple(sorted(existing_used | set(subset)))
                if len(combined) <= 3:
                    warehouse_sets.add(combined)
        for warehouse_tuple in sorted(warehouse_sets):
            candidates.append(
                _candidate(warehouse_tuple, order_lines, available, existing_by_line,
                           prior_wh, existing_used, shipping, reservable)
            )

        full = [candidate for candidate in candidates if candidate.full]
        chosen: Candidate | None
        if full:
            chosen = min(full, key=lambda item: (len(item.used), item.cost, item.used))
        elif order.allow_partial:
            chosen = min(
                candidates,
                key=lambda item: (-item.complete_lines, -item.filled_units, len(item.used),
                                  item.cost, item.used),
            )
        else:
            chosen = None

        if chosen is not None:
            for (line_id, warehouse), quantity in chosen.new_allocations.items():
                line = lines[(order.order_id, line_id)]
                inv_key = (warehouse, line.sku)
                available[inv_key] = available.get(inv_key, 0) - quantity
                allocated_inventory[inv_key] += quantity
                final_allocations[(order.order_id, line_id, warehouse, "reserved")] += quantity

    return dict(final_allocations), dict(allocated_inventory)


def _load_outage(path: Path, shipping: dict[str, tuple[Decimal, Decimal]]) -> str:
    try:
        with path.open("r", encoding="utf-8") as handle:
            value = json.load(handle)
    except OSError as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc
    except json.JSONDecodeError as exc:
        raise InputError(f"{path}:{exc.lineno}:{exc.colno}: invalid JSON: {exc.msg}") from exc
    if not isinstance(value, dict):
        raise InputError(f"{path}: expected a JSON object")
    warehouse = value.get("warehouse_id")
    if not isinstance(warehouse, str) or not warehouse:
        raise InputError(f"{path}: warehouse_id must be a non-empty string")
    if warehouse not in shipping:
        raise InputError(f"{path}: unknown warehouse_id {warehouse!r}")
    effective = value.get("effective_date")
    if not isinstance(effective, str):
        raise InputError(f"{path}: effective_date must be an ISO date string")
    try:
        parsed_date = date.fromisoformat(effective)
    except ValueError as exc:
        raise InputError(f"{path}: invalid effective_date {effective!r}") from exc
    if parsed_date.isoformat() != effective:
        raise InputError(f"{path}: effective_date must use YYYY-MM-DD format")
    if not isinstance(value.get("reason"), str):
        raise InputError(f"{path}: reason must be a string")
    return warehouse


def _as_preserved(
    allocations: dict[tuple[str, str, str, str], int], outage_warehouse: str
) -> list[ExistingAllocation]:
    preserved = []
    for (order_id, line_id, warehouse, status), quantity in allocations.items():
        if warehouse != outage_warehouse or status == "shipped":
            preserved.append(ExistingAllocation(order_id, line_id, warehouse, quantity, status))
    return preserved


def plan(input_dir: Path, output_dir: Path) -> None:
    orders, lines, shipping, inventory, inventory_rows, existing = _load_inputs(input_dir)
    prior_allocations, prior_allocated_inventory = _make_plan(
        orders, lines, shipping, inventory, existing
    )

    outage_path = input_dir / "warehouse_outage.json"
    changes: list[tuple[object, ...]] | None = None
    if outage_path.exists():
        outage_warehouse = _load_outage(outage_path, shipping)
        preserved = _as_preserved(prior_allocations, outage_warehouse)
        final_allocations, allocated_inventory = _make_plan(
            orders, lines, shipping, inventory, preserved, {outage_warehouse}
        )
        changes = []
        for key in sorted(set(prior_allocations) | set(final_allocations)):
            before = prior_allocations.get(key, 0)
            after = final_allocations.get(key, 0)
            delta = after - before
            if delta:
                changes.append(("warehouse_outage", *key, before, after, delta))
    else:
        final_allocations = prior_allocations
        allocated_inventory = prior_allocated_inventory

    allocated_by_line: dict[tuple[str, str], int] = defaultdict(int)
    for (order_id, line_id, _warehouse, _status), quantity in final_allocations.items():
        allocated_by_line[(order_id, line_id)] += quantity

    output_dir.mkdir(parents=True, exist_ok=True)
    _write_csv(
        output_dir / "allocations.csv",
        ("order_id", "line_id", "warehouse_id", "quantity", "status"),
        ((*key[:3], quantity, key[3]) for key, quantity in sorted(final_allocations.items())),
    )
    backorder_rows = []
    for key, line in sorted(lines.items()):
        allocated = allocated_by_line.get(key, 0)
        backordered = line.requested_qty - allocated
        if backordered > 0:
            backorder_rows.append(
                (line.order_id, line.line_id, line.sku, line.requested_qty, allocated, backordered)
            )
    _write_csv(
        output_dir / "backorders.csv",
        ("order_id", "line_id", "sku", "requested_qty", "allocated_qty", "backorder_qty"),
        backorder_rows,
    )
    _write_csv(
        output_dir / "inventory_after.csv",
        ("warehouse_id", "sku", "on_hand", "allocated_qty", "remaining_qty"),
        ((warehouse, sku, on_hand, allocated_inventory.get((warehouse, sku), 0),
          on_hand - allocated_inventory.get((warehouse, sku), 0))
         for warehouse, sku, on_hand in sorted(inventory_rows)),
    )
    if changes is not None:
        _write_csv(
            output_dir / "allocation_changes.csv",
            ("stage", "order_id", "line_id", "warehouse_id", "status",
             "before_qty", "after_qty", "delta_qty"),
            changes,
        )


def _write_csv(path: Path, header: Sequence[str], rows: Iterable[Sequence[object]]) -> None:
    try:
        with path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.writer(handle, lineterminator="\n")
            writer.writerow(header)
            writer.writerows(rows)
    except OSError as exc:
        raise InputError(f"cannot write {path}: {exc}") from exc


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Plan deterministic multi-warehouse fulfillment")
    parser.add_argument("input_dir", type=Path)
    parser.add_argument("--output", required=True, type=Path, dest="output_dir")
    args = parser.parse_args(argv)
    try:
        plan(args.input_dir, args.output_dir)
    except InputError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
